import re


def get_bsc_dx_error(bsc_error):
    """Get dx number and error msg from bsc output"""
    dx_number = re.search(r'\d+', bsc_error[0])
    try:
        error_msg = bsc_error[1]
        dx_number = dx_number.group(0)
    except (IndexError, AttributeError):
        error_msg = bsc_error[0]
        dx_number = None
    return dx_number, error_msg.strip()
